css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--sand:#BBAFA3;--mulberry:#5E3A3C;--clay:#8C5B46;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left;background:var(--bone);color:var(--ink)}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--mulberry)}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.pw h2{font-family:var(--head);font-weight:500;font-size:60px;line-height:1.08;letter-spacing:0;margin:0;text-wrap:balance;text-indent:-.0333em}
.intro{margin:24px 0 0;max-width:36em}
.close{font-family:var(--head);font-style:italic;font-weight:500;font-size:34px;line-height:1.2;margin:72px 0 0}
.grid5{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:48px 32px;margin-top:72px}
.pr{border-top:1px solid var(--sand);padding-top:24px}
.pr .ic{color:var(--mulberry);line-height:0}
.pr .ic svg{display:none}
.pr .ic[data-icon=i1] .i1,.pr .ic[data-icon=i2] .i2,.pr .ic[data-icon=i3] .i3,.pr .ic[data-icon=i4] .i4,.pr .ic[data-icon=i5] .i5,.pr .ic[data-icon=i6] .i6,.pr .ic[data-icon=i7] .i7,.pr .ic[data-icon=i8] .i8,.pr .ic[data-icon=i9] .i9,.pr .ic[data-icon=i10] .i10{display:block}
.pr .ic svg *{fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round}
.pr .ic svg .dot{fill:currentColor}
.pr .nm{margin:18px 0 0;font-family:var(--label);font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:var(--mulberry)}
.pr .ln{margin:8px 0 0}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
@media (max-width:1199px){.grid5{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.close{font-size:27px;margin-top:44px}.grid5{grid-template-columns:1fr;gap:28px;margin-top:40px}.pr{display:grid;grid-template-columns:48px 1fr;column-gap:20px}.pr .ic{grid-row:span 2}.pr .nm{margin-top:4px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
